# --- Deteccao de hardware + diagnostico de GPU ----------------------------
# Tres camadas precisam estar OK para usar 100% da GPU:
#   (1) XGBoost com build CUDA   -> treina as arvores na GPU;
#   (2) GPU + driver utilizaveis -> o device cuda:0 responde ao probe;
#   (3) cupy FUNCIONAL           -> move os DADOS para a GPU. Sem ele o XGBoost
#       ainda treina na GPU, mas copia os dados host->device a cada chamada
#       (resultado correto, porem mais lento e com o warning 'mismatched
#       devices'). Atencao: cupy SEM nvrtc/CUDA_PATH ate importa, mas QUEBRA no
#       primeiro kernel -- por isso so o consideramos util se ele realmente
#       compilar/rodar um kernel; caso contrario caimos para a CPU com seguranca.
import os
import glob
import warnings
import importlib.util
import numpy as np
import xgboost as xgb

N_JOBS = max(1, (os.cpu_count() or 2) - 1)  # deixa 1 nucleo livre p/ a MLflow UI/servidor


def detect_xgb_device():
    """Probe real: tenta um fit minimo em CUDA. Sucesso => 'cuda'; qualquer
    falha (build CPU-only, sem GPU/driver, OOM) => 'cpu'."""
    try:
        _X = np.random.rand(64, 4).astype(np.float32)
        _y = np.random.rand(64).astype(np.float32)
        _m = xgb.XGBRegressor(
            n_estimators=4, device="cuda", tree_method="hist", n_jobs=N_JOBS
        )
        _m.fit(_X, _y)
        _cfg = _m.get_booster().save_config()
        if "cuda" not in _cfg and "gpu" not in _cfg:
            return "cpu"  # rodou, mas o booster nao reporta cuda
        return "cuda"
    except Exception:
        return "cpu"


def _xgb_cuda_build():
    """True/False se o XGBoost foi compilado com CUDA; None se indeterminado."""
    try:
        return bool(xgb.build_info().get("USE_CUDA", False))
    except Exception:
        return None


def _register_pip_cuda_dlls():
    """Se os wheels nvidia-*-cu12 (nvrtc, cudart, ...) estiverem instalados,
    adiciona seus diretorios bin ao loader de DLL do Windows para que o cupy
    consiga carrega-los. No-op em Linux/quando nao existirem."""
    try:
        spec = importlib.util.find_spec("nvidia")
        for loc in (spec.submodule_search_locations or []) if spec else []:
            for b in glob.glob(os.path.join(loc, "*", "bin")):
                try:
                    os.add_dll_directory(b)
                except (OSError, AttributeError):
                    pass
    except Exception:
        pass


def _probe_cupy():
    """(ok, versao, detalhe). 'ok' so e True se o cupy COMPILAR e RODAR um
    kernel -- exatamente o que o XGBoost dispara ao devolver o predict na GPU.
    Importar nao basta: cupy sem nvrtc/CUDA_PATH importa, mas estoura no kernel."""
    _register_pip_cuda_dlls()
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        try:
            import cupy as cp
        except Exception as exc:
            return False, None, f"nao instalado ({type(exc).__name__})"
        ver = getattr(cp, "__version__", "?")
        try:
            _ = float((cp.arange(8, dtype=cp.float32) + 1.0).sum())  # forca nvrtc
            return True, ver, "kernel CUDA compilado e executado"
        except Exception as exc:
            tail = (str(exc).splitlines() or [type(exc).__name__])[-1].strip()
            return False, ver, tail


def _gpu_info():
    """(nome, memoria_GB) via cupy runtime (nao precisa de nvrtc); ou (None, None)."""
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            import cupy as cp
        p = cp.cuda.runtime.getDeviceProperties(0)
        name = p["name"].decode() if isinstance(p["name"], bytes) else p["name"]
        return name, p["totalGlobalMem"] / 1024 ** 3
    except Exception:
        return None, None


DEVICE = detect_xgb_device()
_XGB_CUDA = _xgb_cuda_build()
_CUPY_OK, _CUPY_VER, _CUPY_DETAIL = _probe_cupy()
_GPU_NAME, _GPU_MEM_GB = _gpu_info() if DEVICE == "cuda" else (None, None)


def _row(label, state, extra=""):
    tag = "OK   " if state is True else ("n/a  " if state is None else "FALTA")
    return f"  {label:.<28} {tag} {extra}".rstrip()


print("=" * 66)
print("  DIAGNOSTICO DE HARDWARE (XGBoost / GPU)")
print("-" * 66)
print(_row("XGBoost build CUDA", _XGB_CUDA, f"(xgboost {xgb.__version__})"))
print(_row("GPU utilizavel (cuda:0)", DEVICE == "cuda",
          f"({_GPU_NAME}, {_GPU_MEM_GB:.1f} GB)" if _GPU_NAME else ""))
print(_row("cupy (dados na GPU)", _CUPY_OK,
          f"(cupy {_CUPY_VER})" if _CUPY_OK
          else (f"(cupy {_CUPY_VER}: {_CUPY_DETAIL})" if _CUPY_VER
                else f"({_CUPY_DETAIL})")))
print("-" * 66)
if DEVICE == "cuda" and _CUPY_OK:
    print("  VEREDITO: 100% GPU. Treino E dados na GPU (cuda:0); sem warning")
    print("            de mismatch, performance maxima.")
elif DEVICE == "cuda":
    print("  VEREDITO: GPU PARCIAL (ok p/ uso). O XGBoost TREINA na GPU, mas os")
    print("            DADOS ficam na CPU -> resultados corretos, porem com o")
    print("            warning 'mismatched devices' e um pouco mais lento.")
    if _CUPY_VER is None:
        print("            Para 100% GPU: pip install cupy-cuda12x  (CUDA 12) ou")
        print("            cupy-cuda11x (CUDA 11) e reinicie o kernel.")
    else:
        print("            cupy esta instalado mas nao compila kernels:")
        print(f"              motivo: {_CUPY_DETAIL}")
        print("            Para 100% GPU instale o CUDA Toolkit 12.x (define")
        print("            CUDA_PATH) e reinicie o kernel.")
else:
    _why = ("XGBoost sem build CUDA" if _XGB_CUDA is False
            else "nenhuma GPU CUDA utilizavel (build/driver/sem GPU)")
    print(f"  VEREDITO: CPU. {_why}; rodando com n_jobs={N_JOBS}.")
print("=" * 66)


# Parametros base reutilizados por TODO modelo deste notebook. Centralizar aqui
# garante que device/tree_method/n_jobs nunca divirjam entre as celulas.
XGB_BASE_PARAMS = dict(
    tree_method="hist",     # 'hist' e o backend que roda em GPU com device=cuda
    device=DEVICE,
    n_jobs=N_JOBS,
)


def to_device_frame(X):
    """Move as features para a GPU (cupy) quando DEVICE='cuda' E o cupy esta
    FUNCIONAL (ver diagnostico acima). Sem cupy funcional, devolve um array
    contiguo float32 na CPU: o XGBoost copia host->device internamente e emite
    o warning de mismatch, mas NAO quebra. Em CPU puro e no-op."""
    if DEVICE != "cuda":
        return X
    if not _CUPY_OK:
        return np.ascontiguousarray(np.asarray(X, dtype=np.float32))
    import cupy as cp
    return cp.asarray(np.ascontiguousarray(np.asarray(X, dtype=np.float32)))


def predict_aligned(model, X):
    """Predicao consistente com o device do treino: em GPU com cupy funcional
    mantem os dados no device; sem cupy usa CPU (sem quebrar); em CPU e no-op."""
    return model.predict(to_device_frame(X))


